"""Offline scientific report, separating oracle complexity and CPU simulation."""
import base64
from html import escape
import json
from pathlib import Path
import statistics as st
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from .common import ROOT,dump
from .circuits import bernstein_vazirani,grover


def build_report(directory):
    root=Path(directory);read=lambda name:json.loads((root/name).read_text());protocol=read('protocol.json');env=read('environment.json');algorithms=read('algorithm_runs.json');search=read('grover_runs.json');noise=read('noise_runs.json');qml=read('qml_runs.json');vqe=read('vqe_runs.json');qaoa=read('qaoa_runs.json');anneal=read('annealing_runs.json');figures=root/'figures';figures.mkdir(exist_ok=True);images=[]
    summary={'qml':[],'noise':[],'grover':[]}
    for family in ('moons','circles'):
        for model in ('quantum','rbf'):
            rows=[r for r in qml if r['family']==family and r['model']==model]
            summary['qml'].append({'family':family,'model':model,'mean_accuracy':st.mean(r['accuracy'] for r in rows),'min_accuracy':min(r['accuracy'] for r in rows),'max_accuracy':max(r['accuracy'] for r in rows),'mean_training_s':st.mean(r['training_total_s'] for r in rows),'mean_inference_s':st.mean(r['inference_total_s'] for r in rows),'mean_classifier_scalars':st.mean(r['learned_classifier_scalars'] for r in rows),'trainable_circuit_parameters':0,'circuits_per_model':rows[0]['overlap_circuit_evaluations']})
    for name in ('bv','dj','grover','qpe'):
        for condition in ('ideal','calibrated'):
            rows=[r for r in noise if r['program']==name and r['condition']==condition];success=sum(r['success_count'] for r in rows);shots=sum(r['shots'] for r in rows);p=success/shots;z=1.96;center=(p+z*z/(2*shots))/(1+z*z/shots);half=z*np.sqrt(p*(1-p)/shots+z*z/(4*shots*shots))/(1+z*z/shots)
            summary['noise'].append({'program':name,'condition':condition,'success_probability':p,'wilson_low':float(center-half),'wilson_high':float(center+half),'total_shots':shots,'native_depth':rows[0]['native_depth'],'native_operations':rows[0]['native_operations']})
    for n in protocol['grover_qubits']:
        rows=[r for r in search if r['n']==n]
        summary['grover'].append({'n':n,'size':1<<n,'oracle_calls':rows[0]['grover_rounds'],'verification_calls':1,'classical_expected_checks':rows[0]['classical_uniform_expected_checks'],'mean_observed_classical_checks':st.mean(r['classical_checks'] for r in rows),'success_probability':rows[0]['success_probability'],'classical_median_s':st.median(r['classical_s'] for r in rows),'simulator_median_s':st.median(r['simulator_end_to_end_s'] for r in rows),'cx_gates':rows[0]['basis_operations'].get('cx',0)})
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.18,'figure.dpi':125,'axes.titleweight':'bold'})
    def save(fig,name):fig.tight_layout();fig.savefig(figures/name,bbox_inches='tight');plt.close(fig);images.append(name)
    fig,axes=plt.subplots(1,2,figsize=(11.5,4.7));g=summary['grover'];x=[r['size'] for r in g]
    axes[0].loglog(x,[r['classical_expected_checks'] for r in g],'o--',label='Classical uniform-target expectation',color='#8b7866');axes[0].loglog(x,[r['mean_observed_classical_checks'] for r in g],'.:',label='Classical observed mean',color='#c29a5d');axes[0].loglog(x,[r['oracle_calls']+1 for r in g],'s-',label='Grover + one verification',color='#087f8c');axes[0].set_xlabel('Candidates N');axes[0].set_ylabel('Oracle checks/calls');axes[0].set_title('Query model, not a gate/time model');axes[0].legend(fontsize=8)
    axes[1].loglog(x,[r['classical_median_s']*1000 for r in g],'o-',label='Actual classical scan',color='#8b7866');axes[1].loglog(x,[r['simulator_median_s']*1000 for r in g],'s-',label='Build + transpile + simulate + sample',color='#087f8c');axes[1].set_xlabel('Candidates N');axes[1].set_ylabel('Median CPU wall time (ms)');axes[1].set_title('Measured SDK simulator overhead');axes[1].legend(fontsize=8);save(fig,'grover.png')
    fig,ax=plt.subplots(figsize=(9.5,4.4));positions=np.arange(4)
    for i,condition in enumerate(('ideal','calibrated')):
        rows=[r for r in summary['noise'] if r['condition']==condition];p=np.array([r['success_probability'] for r in rows]);low=np.array([r['wilson_low'] for r in rows]);high=np.array([r['wilson_high'] for r in rows]);ax.bar(positions+(i-.5)*.34,p,.34,color=('#8b7866','#087f8c')[i],label=('Paired ideal Aer','Historical Manila noise')[i],yerr=np.maximum(0,np.vstack((p-low,high-p))),capsize=3)
    ax.set_xticks(positions,['Hidden string','Balanced decision','Grover mark','Phase estimate']);ax.set_ylim(0,1.08);ax.set_ylabel('Correct-outcome fraction');ax.set_title('Noise on the same transpiled circuits');ax.legend(fontsize=9);save(fig,'noise.png')
    fig,axes=plt.subplots(1,2,figsize=(11.5,4.5))
    for i,model in enumerate(('quantum','rbf')):
        rows=[r for r in summary['qml'] if r['model']==model];p=np.array([r['mean_accuracy'] for r in rows]);ranges=np.array([[r['mean_accuracy']-r['min_accuracy'] for r in rows],[r['max_accuracy']-r['mean_accuracy'] for r in rows]])
        axes[0].bar(np.arange(2)+(i-.5)*.33,p,.33,label=('Quantum fidelity kernel','Classical RBF kernel')[i],color=('#087f8c','#d88a35')[i],yerr=ranges,capsize=3);axes[1].bar(np.arange(2)+(i-.5)*.33,[r['mean_training_s'] for r in rows],.33,label=('Quantum fidelity kernel','Classical RBF kernel')[i],color=('#087f8c','#d88a35')[i])
    axes[0].set_ylim(0,1.05);axes[0].set_ylabel('Held-out accuracy');axes[0].set_title('Same split, features and SVC learner');axes[1].set_yscale('log');axes[1].set_ylabel('Mean kernel construction + SVC fit (s, log)');axes[1].set_title('Training cost includes kernel generation')
    for ax in axes:ax.set_xticks(range(2),['Moons','Circles'])
    axes[0].legend(fontsize=8)
    save(fig,'qml.png')
    fig,axes=plt.subplots(1,2,figsize=(11.5,4.5))
    for r in vqe:axes[0].semilogy(range(len(r['trace'])),[max(point['energy']-r['exact_energy'],1e-12) for point in r['trace']],label=f'seed {r["seed"]}')
    axes[0].set_xlabel('Adam update');axes[0].set_ylabel('Energy gap to exact eigensolver');axes[0].set_title('VQE with parameter-shift gradients');axes[0].legend(fontsize=8)
    for depth in (1,2):
        rows=[r for r in qaoa if r['depth']==depth];values=[r['ground_probability'] for r in rows];axes[1].bar(depth,st.mean(values),color=('#087f8c','#d88a35')[depth-1],yerr=[[st.mean(values)-min(values)],[max(values)-st.mean(values)]],capsize=4)
    axes[1].set_xticks([1,2],['QAOA p=1','QAOA p=2']);axes[1].set_ylim(0,1);axes[1].set_ylabel('Mean ground-state sampling probability');axes[1].set_title('Finite optimizer budget; no global claim');save(fig,'hybrid.png')
    for name,qc in [('bv_circuit',bernstein_vazirani(3,5)),('grover_circuit',grover(2,3))]:
        fig=qc.draw(output='mpl',fold=-1,scale=.8);fig.savefig(figures/(name+'.png'),bbox_inches='tight',dpi=130);plt.close(fig);images.append(name+'.png')
    def table(head,rows):return '| '+' | '.join(head)+' |\n| '+' | '.join('---' for _ in head)+' |\n'+''.join('| '+' | '.join(map(str,row))+' |\n' for row in rows)
    def pic(name,caption):return f'![{caption}](figures/{name})\n\n{caption}'
    sections=[]
    def add(title,body):sections.append((title,body))
    add('Track I: Quantum Algorithms and QML Comparison','Prepared for Akshat Tikaria, roll 241070005. Optimization Techniques, Assignment 8.\n\nThis is a CPU simulation study using Qiskit Statevector and Qiskit Aer, explicit algorithm circuits, a saved device-calibration noise model, and matched quantum/classical kernel classifiers. No physical quantum processor was used. Smaller logical oracle counts are distinguished from physical gates and CPU wall time; no practical quantum speedup is claimed.')
    pairs=[(next(r for r in summary['qml'] if r['family']==family and r['model']=='quantum'),next(r for r in summary['qml'] if r['family']==family and r['model']=='rbf')) for family in ('moons','circles')]
    lower=sum(q['mean_accuracy']<c['mean_accuracy'] for q,c in pairs);slower=sum(q['mean_training_s']>c['mean_training_s'] for q,c in pairs)
    add('Main findings',table(['Dataset','Quantum-kernel SVC accuracy','RBF-kernel SVC accuracy'],[[family,f'{next(r for r in summary["qml"] if r["family"]==family and r["model"]=="quantum")["mean_accuracy"]:.2%}',f'{next(r for r in summary["qml"] if r["family"]==family and r["model"]=="rbf")["mean_accuracy"]:.2%}'] for family in ('moons','circles')])+f'\nEach value averages {len(protocol["seeds"])} dataset/split seeds. The fixed two-qubit kernel scores lower on {lower} of two datasets and takes longer to train in simulation on {slower} of two. This does not rank all possible QML models. Grover exhibits its expected logical query scaling while the simulator is much slower than the tiny classical search. The historical device noise reduces success in the four tested programs. All outcomes and finite-budget optimizer statuses are retained.')
    add('Setup, source and existing coverage',table(['Component','Recorded value'],[['Python',env['python']],['Qiskit / Aer',env['versions']['qiskit']+' / '+env['versions']['qiskit-aer']],['Runtime snapshot provider',env['versions']['qiskit-ibm-runtime']],['scikit-learn',env['versions']['scikit-learn']],['Main seeds',str(protocol['seeds'])],['Noise shots per condition/seed',protocol['shots']],['Classifier train / held-out records',f'{protocol["qml_train"]} / {protocol["qml_test"]}'],['Thread policy','One numerical-library thread; Aer max_parallel_threads=1']])+'\nThe supplied quantum deck has 41 slides. It explicitly teaches Deutsch, Grover, VQE, QAOA, parameterized circuits and barren plateaus. Assignment Section 5 additionally names Deutsch-Jozsa, Bernstein-Vazirani, QFT, QPE, Shor, annealing and quantum kernels, all demonstrated here. Track C already supplies parameter-shift/SPSA/QNG, finite-shot VQE and gradient-concentration diagnostics; unchanged earlier summaries/audit/protocols are included with hashes. They remain earlier C measurements, not fresh I executions. Exact serving-model revision and full conversation exports remain disclosure tasks.')
    add('Explicit algorithms and mathematical checks',table(['Algorithm','Experiment and verification','Scope'],[['Deutsch','All four one-bit Boolean oracles; constant/balanced decision from one query','Promise problem, two classical evaluations in the deterministic worst case'],['Deutsch-Jozsa','Two constants, linear/nonlinear balanced three-bit truth tables; promised decision','Truth-table oracle construction is exponential and is charged as one abstract black-box call only'],['Bernstein-Vazirani','Three-bit hidden strings 000, 011, 101, 111','Efficient explicit CNOT oracle; one logical quantum query versus n classical bit queries'],['QFT','2–4-qubit circuits compared with the complete dense Fourier unitary','Uniform measurement alone is not accepted as correctness proof'],['QPE','Exact phases 0 and 3/8; off-grid phase 1/3','Full distribution checked against the finite Fourier/Dirichlet formula'],['Shor order finding','N=15, multipliers 2, 7, 11, 14; QPE and continued-fraction/GCD postprocessing','Dense reversible modular multiply, not scalable arithmetic or a general factoring speed benchmark'],['Quantum annealing','Closed-system gate-based Trotter schedule on a four-bit Max-Cut problem','Separate dense time-evolution reference and classical simulated annealing; no annealer hardware']])+'\nThe QFT uses positive Fourier phases, inverse QFT in phase estimation, and little-endian register integers. Shor leaves unused basis state 15 unchanged, preserving unitarity. Postprocessing rejects unhelpful zero/half-period or minus-one results rather than searching periods classically to manufacture success. The a=14 failure control is retained. No built-in complete algorithm constructors replace the explicit circuits.')
    add('Two handwritten circuit examples',pic('bv_circuit.png','Bernstein-Vazirani for hidden string 101. The ancilla creates phase kickback, CNOTs implement the oracle, and final Hadamards recover the hidden bits.')+'\n\n'+pic('grover_circuit.png','Two-qubit Grover search for mark 11 with one amplification round. Oracle and diffuser are explicit gates. Its global phase convention does not affect outcome probabilities.'))
    add('Grover query complexity and measured time',pic('grover.png','The query plot separates the analytic uniform-target classical expectation from the observed mean checks on the sampled marks. The time plot is CPU simulation, not QPU execution.')+'\n'+table(['N','Grover search + verify','Classical uniform expected checks','Observed classical mean','Ideal marked probability','Compiled CX gates','Median simulator ms'],[[r['size'],f'{r["oracle_calls"]} + 1',f'{r["classical_expected_checks"]:.1f}',f'{r["mean_observed_classical_checks"]:.1f}',f'{r["success_probability"]:.5f}',r['cx_gates'],f'{r["simulator_median_s"]*1000:.3f}'] for r in summary['grover']])+'\nWith one marked item, r is rounded from pi/(4 asin(1/sqrt(N))) minus 1/2; the marked probability is sin squared of (2r+1)asin(1/sqrt(N)). The known black-box advantage is quadratic query scaling. Some sampled targets are found early by linear search, and one amplification attempt is probabilistic. Raw outcomes and verification are retained. Circuit construction, MCX decomposition, transpilation, statevector evolution and output sampling have costs absent from the unit-query model; these are included in the recorded simulator total. Transpilation supplies the u/cx resource count, while Statevector evolves the logical circuit; the total includes this inspection compilation and is not bare evolution time. Component timings remain separate. No QRAM, realistic database loading, fault tolerance or scalable oracle synthesis is demonstrated.')
    add('Historical calibrated hardware-noise model',pic('noise.png',f'Each condition pools {len(protocol["seeds"])*protocol["shots"]:,} emulated shots. Error bars are 95% Wilson intervals for shot sampling only, not uncertainty in the calibration or noise model.')+'\n'+table(['Program','Ideal correct fraction','Calibrated correct fraction','Native depth'],[[name,f'{next(r for r in summary["noise"] if r["program"]==name and r["condition"]=="ideal")["success_probability"]:.2%}',f'{next(r for r in summary["noise"] if r["program"]==name and r["condition"]=="calibrated")["success_probability"]:.2%}',next(r for r in summary['noise'] if r['program']==name)['native_depth']] for name in ('bv','dj','grover','qpe')])+'\nThe preserved FakeManila snapshot is dated 2024-05-27T15:27:23-03:00. Configuration, properties, provider version, license, source hashes and the generated Aer noise model are included. FrozenManila reads those exact local files. NoiseModel.from_backend approximates gate/depolarizing, thermal-relaxation and readout errors. It does not reproduce all crosstalk, drift, correlated errors or current hardware behavior. Paired ideal and noisy runs execute the same transpiled physical circuits, layout and measurement mapping. No live service, credentials, paid job or physical QPU was used. For DJ, any nonzero output is a correct balanced decision; criteria differ between programs.')
    add('QML versus a matched classical learner',pic('qml.png','Accuracy bars average dataset/split seeds and show their min–max range. Training time includes exact kernel construction and SVC fitting; these are dataset-seed observations, not repeated timing trials on one fixed dataset.')+'\n'+table(['Dataset','Kernel','Mean test accuracy','Mean training s','Mean inference s','Mean dual coefficients + bias','Overlap circuits/model'],[[r['family'],r['model'],f'{r["mean_accuracy"]:.2%}',f'{r["mean_training_s"]:.6f}',f'{r["mean_inference_s"]:.6f}',f'{r["mean_classifier_scalars"]:.1f}',r['circuits_per_model']] for r in summary['qml']])+'\nBoth models use the same stratified split, the same two features transformed by training-fitted StandardScaler then bounded by (pi/2)*tanh, C=1, and the same precomputed-kernel SVC solver. The classical RBF gamma is computed from training-feature variance. No test labels are used to fit preprocessing or select the fixed kernel configuration. Raw features, split indices, transforms, Gram matrices, support vectors, dual coefficients, bias and predictions are saved.\n\nThe two-qubit feature map uses two layers of Hadamards, feature RZ rotations and a ZZ interaction. The fidelity kernel is the all-zero probability of U(x_j) inverse composed after U(x_i). Training executes upper-triangle overlap circuits, mirrors the exact kernel, and sets ideal self-overlaps to one. Test executes every test/train pair. There is no amplitude-cache shortcut in the measured implementation. Each overlap has 28 logical gates, including 8 CX gates. Circuit building and inverse definitions are inside kernel timing. The audit independently derives four amplitudes analytically and verifies every kernel entry.\n\nThere are zero trainable circuit weights in this fixed kernel. Learned classifier scalar count means support-vector dual coefficients plus bias, not zero learned ML parameters. Training-point storage and four common scaler numbers are excluded from that count. Exact simulator probabilities require no shots; hardware kernel estimation would require many measurements per overlap. The reported circuit count is exact simulator evaluations, not physical QPU shots. This tiny state space is readily classically simulable and supplies no computational-hardness advantage.\n\nThe separate kernel-shot study applies binomial test-kernel estimates at 128, 512 and 2048 shots while holding the ideal-trained classifier fixed. It is synthetic shot sensitivity, not calibrated noisy training, and it does not project or refit a noisy training Gram matrix.')
    add('Hybrid optimization and annealing',pic('hybrid.png','VQE uses four trainable rotation angles and parameter-shift Adam. QAOA uses 2p angles and Powell under a fixed maximum objective-call budget; error bars span random starts.')+'\n'+table(['VQE seed','Final energy gap','Circuit evaluations','Runtime s'],[[r['seed'],f'{r["gap"]:.6g}',r['circuit_evaluations'],f'{r["runtime_s"]:.4f}'] for r in vqe])+'\n'+table(['QAOA depth / seed','Expected cut / exact 4','Ground probability','Calls','Optimizer success'],[[f'{r["depth"]} / {r["seed"]}',f'{r["expected_cut"]:.4f}',f'{r["ground_probability"]:.3%}',r['circuit_evaluations'],r['optimizer_success']] for r in qaoa])+'\nThe VQE Hamiltonian is an explicitly declared dimensionless two-qubit example, not a claimed molecular energy. The four-node Max-Cut graph has five edges, uniform expected cut 2.5 and exact optimum 4. All traces, optimizer limits and local outcomes remain present; p=2 budget termination is not mislabeled as convergence. Earlier C uses its own declared Hamiltonians/QUBO inputs and budgets, so its values are not merged as additional repetitions here.\n\n'+table(['Annealing T','Ground probability','Dense reference ground probability','Trotter/dense state fidelity'],[[r['total_time'],f'{r["ground_probability"]:.5f}',f'{r["dense_ground_probability"]:.5f}',f'{r["dense_state_fidelity"]:.6f}'] for r in anneal['gate_based_adiabatic_simulation']])+'\nAnnealing simulates H(s)=-(1-s)sum(X)+s*(-cut), with 128 midpoint Trotter steps. A dense time-ordered midpoint evolution checks the approximation; fidelity measures discretization error rather than noise. The classical Metropolis annealing baseline makes 513 objective calls per seed and is retained separately. On four bits, exact enumeration needs only 16 candidate energies. No quantum-annealer embedding was executed. Real sparse-coupling annealers can require chains and extra physical qubits, finite precision and chain-strength choices; logical QUBO size alone is not hardware cost.')
    earlier=json.loads((ROOT/'inputs/track_d/summary.json').read_text());d=[r for r in earlier['scheduling'] if r['family']=='irregular' and r['method']=='work_stealing' and r['workers'] in (2,4,8)]
    add('Contrast with Track D parallel measurements',table(['Track D workers','Measured steady speedup','Parallel efficiency','Measured end-to-end speedup'],[[r['workers'],f'{r["speedup"]:.3f}',f'{r["efficiency"]:.3f}',f'{r["end_to_end_speedup"]:.3f}'] for r in d])+'\nThese are unchanged earlier D irregular-workload, work-stealing measurements with hashes and original environment/protocol. They describe CPU processes doing real work; end-to-end numbers include startup/teardown. Grover’s quadratic statement instead compares black-box oracle calls. CPU parallelism is limited by serial fractions and communication/startup costs; quantum algorithms also incur data loading, oracle construction, measurement, routing, noise and possible error-correction costs. Neither metric can be substituted for the other, and the experiments are not plotted on a shared speedup scale. Prior C gradient-concentration diagnostics illustrate trainability limits without proving an asymptotic barren plateau for all models.')
    add('Verification and remaining work','The host tests use independent Fourier matrices, phase-estimation distributions, modular-permutation checks, VQE dense Hamiltonians/finite differences, Grover formulas, annealing products and analytical kernel amplitudes. The retained-data audit reloads QPY circuits, checks all input/source/evidence hashes, recomputes hybrid objective histories, verifies raw classifiers from stored dual coefficients and can exactly replay the seeded Aer shot runs with pinned versions. No timings are replaced.\n\nA genuine integration failure attempted to JSON-serialize the SDK’s Rust EdgeList coupling map directly. It stopped the first pilot after noisy-circuit results; the fix explicitly converts each edge into native lists. The original error, original/fixed commits, regression and complete rerun are retained. All implementation/documentation are AI-assisted ChatGPT/Codex work; no manual student correction, full chat export or independent second-AI-tool comparison is claimed.\n\nTrack I’s requested algorithm, QML, calibrated-noise-model and parallel-comparison experiments are provided. J, overall assignment integration, unresolved research reproductions, exact serving-model/export disclosure, independent two-tool comparison, public repository and live demonstration remain open. Earlier packages remain unchanged.')
    add('Primary references','IBM Quantum algorithm/phase-estimation/factoring learning: https://quantum.cloud.ibm.com/learning/en/courses/fundamentals-of-quantum-algorithms/phase-estimation-and-factoring/shor-algorithm\n\nIBM noise-model documentation: https://quantum.cloud.ibm.com/docs/en/guides/build-noise-models\n\nQuantum kernel feature-space inspiration, not a reproduction of the hardware study: https://arxiv.org/abs/1804.11326\n\nscikit-learn SVC API: https://scikit-learn.org/1.8/modules/generated/sklearn.svm.SVC.html\n\nSupplied Assignment 8 Section 5 / Track I and supplied Chapter 6 quantum slides. Public references checked 2026-11-04. All new numeric results come from this package’s actual CPU simulations; C/D references are explicitly earlier preserved measurements.')
    (root/'REPORT.md').write_text('\n\n'.join('# '+title+'\n\n'+body for title,body in sections)+'\n')
    def render(body):
        lines=body.splitlines();out=[];i=0
        while i<len(lines):
            line=lines[i]
            if line.startswith('| '):
                data=[]
                while i<len(lines) and lines[i].startswith('| '):data.append([v.strip() for v in lines[i].strip('|').split('|')]);i+=1
                out.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+escape(v)+'</th>' for v in data[0])+'</tr></thead><tbody>')
                for row in data[2:]:out.append('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in row)+'</tr>')
                out.append('</tbody></table></div>');continue
            if line.startswith('!['):
                name=line.split('(figures/',1)[1].rstrip(')');out.append('<img alt="'+escape(line[2:line.index(']')])+'" src="data:image/png;base64,'+base64.b64encode((figures/name).read_bytes()).decode()+'">')
            elif line:out.append('<p>'+escape(line)+'</p>')
            i+=1
        return '\n'.join(out)
    html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track I Quantum Algorithms and QML</title><style>body{margin:0;background:#eef2f6;color:#203540;font:16px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:32px auto;background:white;padding:36px;border-top:8px solid #087f8c;border-radius:12px}h1{font-size:32px;line-height:1.2}h2{font-size:24px;color:#075e68;margin-top:40px}img{width:100%;height:auto;margin:18px 0}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;border-bottom:1px solid #dce6e9;text-align:left}th{background:#e8f2f3}p{overflow-wrap:anywhere}@media(max-width:700px){main{margin:0;padding:20px}}</style><main>'
    for i,(title,body) in enumerate(sections):tag='h1' if i==0 else 'h2';html+=f'<{tag}>'+escape(title)+f'</{tag}>'+render(body)
    (root/'report.html').write_text(html+'</main></html>');dump(root/'summary.json',summary);return images
